import {BLOCKS,THEMES,TEMPLATES,esc,uid,createBlock,createProject,normalizeTheme,validateProject,generateDocument,generateParts,sandboxDocument,contrastInk,CSP} from './engine.js';

const ICONS={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/>',palette:'<path d="M12 3a9 9 0 1 0 0 18h1a2 2 0 0 0 0-4h-1a1 1 0 0 1 0-2h4a5 5 0 0 0 5-5c0-4-4-7-9-7Z"/><path d="M7 9h.01M10 6h.01M15 7h.01M6 13h.01" stroke-width="3"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',book:'<path d="M12 5v16M3 4c3-1 6-1 9 1 3-2 6-2 9-1v15c-3-1-6-1-9 1-3-2-6-2-9-1V4Z"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Zm7 0v4m-2-2h4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.01"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.2 9a3 3 0 0 1 5.6 1c0 2-2.8 2-2.8 4m0 3h.01"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',external:'<path d="M14 3h7v7m0-7L10 14M9 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-4"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v4h16v-4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v4h16v-4"/>',desktop:'<rect x="3" y="3" width="18" height="13" rx="2"/><path d="M8 21h8m-4-5v5"/>',tablet:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M12 18h.01"/>',mobile:'<rect x="7" y="2" width="10" height="20" rx="2"/><path d="M11 18h2"/>',undo:'<path d="M3 10h11a6 6 0 1 1 0 12M3 10l5-5m-5 5 5 5"/>',redo:'<path d="M21 10H10a6 6 0 1 0 0 12m11-12-5-5m5 5-5 5"/>',up:'<path d="m5 15 7-7 7 7"/>',down:'<path d="m5 9 7 7 7-7"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',eye:'<path d="M2 12s4-8 10-8 10 8 10 8-4 8-10 8S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',filter:'<path d="M4 7h16M7 12h10M10 17h4"/>',refresh:'<path d="M20 8a9 9 0 1 0 .5 7M20 3v5h-5"/>',file:'<path d="M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8m-8 4h6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||ICONS.spark}</svg>`;
const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const main=$('#main'),details=$('#detail-dialog'),codeDialog=$('#code-dialog'),infoDialog=$('#info-dialog');
const STORAGE='design-atlas.project.v1',FAVS='design-atlas.favorites.v1';
let catalog={skills:[],resources:[],scope:{}},references=[],project=createProject(),selected='',undoStack=[],redoStack=[],storageFailed=false,bootWarning='',detailState=null,codeState=null,previewTimer,saveTimer,toastTimer,draggedLayer='';
const view={name:'library',section:'blocks',filter:'全部',q:'',sort:'default',layout:'grid',page:1,device:'desktop',builderTab:'layers',assetSearch:''};
let favorites=new Set();
try{favorites=new Set(JSON.parse(localStorage.getItem(FAVS)||'[]').filter(x=>typeof x==='string'));const stored=localStorage.getItem(STORAGE);if(stored)project=validateProject(JSON.parse(stored));}catch{bootWarning='先前保存的数据无法读取，已打开一份新草稿。原始数据暂时保留，首次编辑后会保存当前草稿。';}
selected=project.blocks[0]?.uid||'';
const keyOf=item=>`${item.kind||'block'}:${item.id}`;
const licenseOf=item=>typeof item.license==='object'?item.license?.document?.id||'未确认':item.license||'见来源';
const https=url=>typeof url==='string'&&/^https:\/\//i.test(url)?url:'';
const safeLink=(url,label,cls='')=>https(url)?`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`:`<span class="${cls}">${label}</span>`;
const roleName=r=>({design:'设计与创意',build:'搭建与交付',verify:'验证与优化'}[r]||r);
const allItems=()=>[...BLOCKS,...TEMPLATES.map(x=>({...x,kind:'template',category:'整页模板',tags:['完整页面','原创 MIT']})),...references,...catalog.resources,...catalog.skills.map(s=>({...s,kind:'skill'}))];
function toast(message,error=false){clearTimeout(toastTimer);$('#toast-stack').innerHTML=`<div class="toast-item ${error?'error':''}">${icon(error?'info':'check')}<span>${esc(message)}</span></div>`;toastTimer=setTimeout(()=>$('#toast-stack').replaceChildren(),3400);}
function status(text,failed=false){const el=$('#save-status');el.innerHTML=`<i style="background:${failed?'#b48a53':'#699075'}"></i>${esc(text)}`;}
function save(){clearTimeout(saveTimer);status('正在保存…');saveTimer=setTimeout(()=>{try{localStorage.setItem(STORAGE,JSON.stringify(project));storageFailed=false;status('已保存在此浏览器')}catch{storageFailed=true;status('保存失败，请导出项目',true);toast('浏览器存储不可用或空间不足，请导出项目 JSON 保存。',true)}},220);}
function remember(){undoStack.push(JSON.stringify(project));if(undoStack.length>60)undoStack.shift();redoStack=[];}
function mutate(fn,{render=true}={}){remember();fn();save();if(render&&view.name==='builder')renderBuilder();else{schedulePreview();updateHistoryButtons()}}
function undo(){if(!undoStack.length)return;redoStack.push(JSON.stringify(project));project=JSON.parse(undoStack.pop());ensureSelection();save();renderBuilder();}
function redo(){if(!redoStack.length)return;undoStack.push(JSON.stringify(project));project=JSON.parse(redoStack.pop());ensureSelection();save();renderBuilder();}
function ensureSelection(){if(!project.blocks.some(b=>b.uid===selected))selected=project.blocks[0]?.uid||'';}
function updateHistoryButtons(){const a=$('[data-action="undo"]'),b=$('[data-action="redo"]');if(a)a.disabled=!undoStack.length;if(b)b.disabled=!redoStack.length;}
function setView(name,section){view.name=name;if(name==='library'&&!section)section='blocks';if(section){view.section=section;view.filter='全部';view.q='';view.page=1}closeSidebar();render();window.scrollTo(0,0);}
function syncSidebar(){const mobile=matchMedia('(max-width:760px)').matches,open=$('#sidebar').classList.contains('open');$('#sidebar').inert=mobile&&!open;$('#sidebar').setAttribute('aria-hidden',String(mobile&&!open));$('.app-shell').inert=mobile&&open;if(!mobile){$('#sidebar-backdrop').hidden=true;document.body.style.overflow=$$('dialog[open]').length?'hidden':'';}}
function closeSidebar(){const wasOpen=$('#sidebar').classList.contains('open');$('#sidebar').classList.remove('open');$('#sidebar-backdrop').hidden=true;$('#mobile-menu').setAttribute('aria-expanded','false');syncSidebar();document.body.style.overflow=$$('dialog[open]').length?'hidden':'';if(wasOpen)$('#mobile-menu').focus();}
function navigation(){const labels={library:'设计资源库',builder:'页面拼装台',themes:'主题实验室',favorites:'我的收藏'};$('#breadcrumb-current').textContent=view.name==='library'?{blocks:'设计资源库',templates:'整页模板',references:'本地设计参考',opensource:'开源资源索引',skills:'本地设计 Skills'}[view.section]:labels[view.name];$$('[data-view].nav-item').forEach(e=>e.classList.toggle('active',e.dataset.view===view.name&&!(view.name==='library'&&['references','opensource','skills'].includes(view.section))));$$('[data-section].nav-item').forEach(e=>e.classList.toggle('active',view.name==='library'&&e.dataset.section===view.section));$('#favorite-count').textContent=favorites.size;$('#nav-total').textContent=BLOCKS.length;$('#nav-references').textContent=references.length;$('#nav-opensource').textContent=catalog.resources.length;$('#nav-skills').textContent=catalog.skills.length;}
function render(){navigation();if(view.name==='builder')renderBuilder();else if(view.name==='themes')renderThemes();else renderLibrary();hydrateIcons();}
function hydrateIcons(root=document){$$('[data-icon]',root).forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function titleBlock(){const content=view.name==='favorites'?['YOUR VERY OWN COLLECTION','把喜欢的，<em>留在手边。</em>','收藏那些让你眼前一亮的细节，下次灵感会来得更快。']:view.section==='references'?['YOUR LOCAL DESIGN REFERENCES','好设计，<em>有迹可循。</em>','从本地 DESIGN.md 提取视觉特征与配色，选择一种方向，开始自己的创作。']:view.section==='opensource'?['OPEN SOURCE & SOURCE-AVAILABLE','好工具，<em>让想法更近一步。</em>','经过来源核对的组件、动效、图标与模板。查看官方演示，沿着源码继续探索。']:view.section==='skills'?['YOUR LOCAL DESIGN SKILLS','从灵感，到交付，<em>各有所长。</em>','整理本地设计、搭建与验收技能。复制任务提示，交给支持相应技能的工作环境。']:['A LITTLE INSPIRATION. ENDLESS POSSIBILITIES.','把灵感，<em>变成好界面。</em>','探索设计，试试变化，拼出属于你的作品。每一个好想法，都可以从这里开始。'];return `<div class="page-eyebrow"><i></i>${content[0]}</div><div class="page-heading"><div><h1>${content[1]}</h1><p>${content[2]}</p></div><div class="heading-art" aria-hidden="true"><div class="heading-orbit"><span>✳</span></div><small>A SPACE<br>FOR YOUR<br>NEXT IDEA.</small></div></div>`;}
function sectionItems(){if(view.name==='favorites')return allItems().filter(i=>favorites.has(keyOf(i)));return {blocks:BLOCKS,templates:TEMPLATES.map(t=>({...t,kind:'template',category:'整页模板',tags:['完整页面','原创 MIT']})),references,opensource:catalog.resources,skills:catalog.skills.map(s=>({...s,kind:'skill'}))}[view.section]||[];}
function filteredItems(){let items=sectionItems();const q=view.q.toLocaleLowerCase().trim();if(view.filter!=='全部')items=items.filter(i=>i.category===view.filter||i.role===view.filter||i.tags?.includes(view.filter)||(view.filter==='宽松许可'&&['MIT','Apache-2.0','ISC','BSD-3-Clause','BSD-2-Clause','OFL-1.1'].some(x=>licenseOf(i).includes(x))&&i.projectType!=='source-available')||(view.filter==='特殊授权'&&i.projectType==='source-available'));if(q)items=items.filter(i=>[i.name,i.id,i.description,i.descriptionZh,i.category,i.stack,...i.tags||[],...i.capabilities||[]].join(' ').toLocaleLowerCase().includes(q));if(view.sort==='name')items=[...items].sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'));if(view.sort==='favorites')items=[...items].sort((a,b)=>Number(favorites.has(keyOf(b)))-Number(favorites.has(keyOf(a))));return items;}
function renderLibrary(){const sections=[['blocks','可玩模块',BLOCKS.length],['templates','整页模板',TEMPLATES.length],['references','设计参考',references.length],['opensource','开源索引',catalog.resources.length],['skills','Skills',catalog.skills.length]];let filters=['全部'];if(view.name!=='favorites'){if(view.section==='skills')filters.push('design','build','verify');else{filters.push(...new Set(sectionItems().map(i=>i.category)));if(view.section==='opensource')filters.push('宽松许可','特殊授权')}}else filters.push(...new Set(sectionItems().map(i=>i.category)));const items=filteredItems(),pageSize=18,totalPages=Math.max(1,Math.ceil(items.length/pageSize));view.page=Math.min(view.page,totalPages);const current=items.slice((view.page-1)*pageSize,view.page*pageSize);
 const notes={references:'索引包含本地实际存在的全部 75 份参考。这里展示提取的视觉特征与颜色事实，配色可应用到原创模块；品牌资产授权请单独确认。',opensource:`已核实 ${catalog.resources.length} 个资源仓库。目录为本次精选，覆盖主流生态；React Bits 等特殊授权资源有独立标识。卡片提供官方演示与源码入口，未将第三方库安装进本工作台。`,skills:'索引记录本机技能文件的公开能力摘要；文件存在不代表连接器已连接或拥有执行授权。提示词可复制到支持对应技能的环境使用。'};
 main.innerHTML=`${bootWarning?`<div class="restore-banner">${esc(bootWarning)}</div>`:''}${titleBlock()}<div class="stat-strip">${[[BLOCKS.length,'可定制模块','grid'],[references.length,'本地设计参考','book'],[catalog.resources.length,'源码资源','code'],[catalog.skills.length,'设计相关 Skills','spark']].map(([n,label,i])=>`<div class="stat-cell"><span class="stat-icon">${icon(i)}</span><div><strong>${n}<small>项</small></strong><p>${label}</p></div></div>`).join('')}</div><div class="section-toolbar">${view.name==='favorites'?'<div class="seg-tabs"><button class="active">全部收藏 <span>'+favorites.size+'</span></button></div>':`<div class="seg-tabs" role="tablist" aria-label="资源类型">${sections.map(([id,n,c])=>`<button role="tab" aria-selected="${view.section===id}" data-library-section="${id}" class="${view.section===id?'active':''}">${n}<span>${c}</span></button>`).join('')}</div>`}<div class="toolbar-actions"><label class="search-box">${icon('search')}<input id="library-search" type="search" aria-label="搜索设计资源" placeholder="搜索名称、风格或关键词…" value="${esc(view.q)}"><kbd>/</kbd></label><button class="icon-btn ${view.layout==='grid'?'active':''}" data-layout="grid" aria-label="网格视图" aria-pressed="${view.layout==='grid'}">${icon('grid')}</button><button class="icon-btn ${view.layout==='list'?'active':''}" data-layout="list" aria-label="列表视图" aria-pressed="${view.layout==='list'}">${icon('list')}</button></div></div><div class="filter-row">${filters.map(f=>`<button class="filter-chip ${view.filter===f?'active':''}" data-filter="${esc(f)}" aria-pressed="${view.filter===f}">${esc(roleName(f))}</button>`).join('')}<div class="result-meta"><span>找到 <b id="result-count">${items.length}</b> 项设计</span><span>·</span><label class="sr-only" for="sort-select">排列方式</label><select id="sort-select"><option value="default" ${view.sort==='default'?'selected':''}>推荐顺序</option><option value="name" ${view.sort==='name'?'selected':''}>按名称排列</option><option value="favorites" ${view.sort==='favorites'?'selected':''}>收藏优先</option></select>${icon('down')}</div></div>${notes[view.section]&&view.name!=='favorites'?`<div class="catalog-note">${icon('info')}<span>${notes[view.section]}</span></div>`:''}<div class="card-grid ${view.layout==='list'?'list-mode':''}" id="card-grid">${current.length?current.map(renderCard).join(''):emptyLibrary()}</div><div id="pagination">${pagination(totalPages,items.length)}</div><p class="library-endnote">探索 · 修改 · 组合 · 带走代码 <span aria-hidden="true"> ✳ </span> 让每个好想法，有自己的样子。</p>`;
 $('#library-search').addEventListener('input',e=>{view.q=e.target.value;view.page=1;updateGrid()});$('#sort-select').addEventListener('change',e=>{view.sort=e.target.value;view.page=1;updateGrid()});
}
function updateGrid(){const items=filteredItems(),pages=Math.max(1,Math.ceil(items.length/18));view.page=Math.min(view.page,pages);$('#result-count').textContent=items.length;$('#card-grid').innerHTML=items.length?items.slice((view.page-1)*18,view.page*18).map(renderCard).join(''):emptyLibrary();$('#pagination').innerHTML=pagination(pages,items.length);}
function emptyLibrary(){return `<div class="empty-state"><span>✳</span><h2>${view.name==='favorites'?'喜欢的设计，会在这里相遇。':'暂时没有找到这个设计。'}</h2><p>${view.name==='favorites'?'点击资源卡片上的爱心，建立自己的灵感收藏。':'换一个关键词，或者试着清除分类筛选。'}</p><button class="secondary-button" data-action="clear-filters">${view.name==='favorites'?'去发现设计':'清除筛选'} ${icon('arrow')}</button></div>`;}
function pagination(pages,count){return pages>1?`<div class="pagination"><button data-page="${Math.max(1,view.page-1)}" aria-label="上一页" ${view.page===1?'disabled':''}>←</button>${Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${view.page===i+1?'active':''}" ${view.page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<button data-page="${Math.min(pages,view.page+1)}" aria-label="下一页" ${view.page===pages?'disabled':''}>→</button><small>${count} 项</small></div>`:'';}
function referenceTheme(ref){const t=ref.designTokens||{};const colors=(ref.colors||[]).filter(c=>/^#[0-9a-f]{6}$/i.test(c));const accent=t.accent||colors[0]||THEMES[0].accent;const bg=t.bg||THEMES[0].bg;const dark=contrastInk(bg)==='#ffffff';return normalizeTheme({...THEMES[0],...t,accent,bg,surface:t.surface||bg,ink:t.ink||(dark?'#f4f5ef':'#202b25'),muted:t.muted||(dark?'#a8b3a0':'#68746c')});}
function thumb(item){const id=item.id;const f=(body,cls='')=>`<div class="art-frame ${cls}" aria-hidden="true">${body}</div>`;const lines='<div class="art-line"></div><div class="art-line short"></div>';if(item.kind==='reference'){const t=referenceTheme(item);return `<div class="reference-demo" style="--ref-bg:${t.bg};--ref-surface:${t.surface};--ref-ink:${t.ink};--ref-accent:${t.accent};--ref-font:${t.font==='serif'?'Georgia,serif':t.font==='mono'?'Consolas,monospace':'inherit'}" aria-hidden="true"><small>AN ORIGINAL COLOR EXPLORATION</small><strong>Make space<br>for good ideas.</strong><span>✳</span><i></i><div class="ref-mini-panels"><b></b><b></b><b></b></div><em>${esc(item.name)}</em></div>`}if(item.kind==='opensource'||item.kind==='resource')return `<div class="resource-visual" aria-hidden="true"><strong>${esc(item.name)}</strong><small>${esc(item.stack||'OPEN SOURCE')}</small><div class="resource-swatches"><i style="background:#fff"></i><i style="background:#d4dfc5"></i><i style="background:#8da578"></i><i style="background:#45643d"></i></div></div>`;if(item.kind==='skill')return `<div class="skill-visual" aria-hidden="true"><span class="skill-symbol">${{design:'✳',build:'◈',verify:'◎'}[item.role]||'✳'}</span><span class="skill-lines"><b>${esc(item.name)}</b><i></i><i></i></span></div>`;if(item.kind==='template')return f(`<div class="art-mini-nav"><b>✳ forma</b><span></span><span></span></div><div class="art-title">${id==='saas'?'A little more<br>possibility.':id==='workspace'?'Your creative<br>workspace.':'Good ideas.<br>Beautifully made.'}</div><div class="art-spark">✳</div>${lines}<span class="art-button"></span>`,id==='saas'?'dark':'');
 if(['hero-editorial','hero-split','cta'].includes(id))return f(`<div class="art-eyebrow">A SPACE FOR YOUR NEXT IDEA</div><div class="art-title">${id==='cta'?'Make it<br>something good.':id==='hero-split'?'Room for<br>good ideas.':'Less noise.<br>More meaning.'}</div><span class="art-spark">${id==='hero-split'?'◈':'✳'}</span><div class="art-text"></div><span class="art-button"></span>`);
 if(['hero-aurora','spotlight'].includes(id))return f(`<div class="art-aurora"></div><div class="art-eyebrow">A LITTLE EVERYDAY MAGIC</div><div class="art-title">${id==='spotlight'?'Ideas in<br>the spotlight.':'Build something<br>extraordinary.'}</div><span class="art-button"></span><div class="art-bottom-ui"><i></i><i></i><i></i></div>`,'dark center');
 if(id==='bento'||id==='features')return f(`<div class="art-mini-panels"><div>FOR YOUR FOCUS<b>✳</b></div><div>Less, but better.<div class="bars"><i></i><i></i><i></i></div></div><div>Make it yours. ↗</div></div>`);
 if(id==='pricing')return f(`<div class="art-eyebrow">FIND YOUR LITTLE SPACE</div><div class="art-price">${[0,29,79].map(x=>`<div>STUDIO<b>¥${x}</b><i></i><i></i><span class="art-button"></span></div>`).join('')}</div>`);
 if(['contact','login','newsletter','command'].includes(id))return f(`<div class="art-form"><div class="art-eyebrow">${id==='command'?'AT YOUR FINGERTIPS':'HELLO, NEW POSSIBILITY'}</div><strong>${id==='login'?'Welcome back.':id==='newsletter'?'Stay curious.':id==='command'?'Find your next idea.':'Let’s make it happen.'}</strong><div class="art-input"></div><div class="art-input"></div><span class="art-button"></span></div>`);
 if(id==='dashboard'||id==='stats')return f(`<div class="art-eyebrow">YOUR CREATIVE OVERVIEW</div><div class="art-metrics">${['28,460','1,284','92.4%'].map(x=>`<span>THIS MONTH<b>${x}</b></span>`).join('')}</div><div class="art-chart"><svg viewBox="0 0 200 65"><path d="M0 55Q20 65 35 40T65 38T100 25T140 20T180 10L200 3" fill="none" stroke="#839b68" stroke-width="2"/><path d="M0 55Q20 65 35 40T65 38T100 25T140 20T180 10L200 3V65H0Z" fill="#839b681a"/></svg></div>`);
 if(id==='quote'||id==='testimonials')return f(`<div class="art-quote"><span>“</span><p>Good design makes<br>room for good things.</p><small>A THOUGHT WORTH KEEPING</small></div>`);
 if(id==='gallery')return f(`<div class="art-eyebrow">SELECTED WORKS</div><div class="art-tiles"><div>f.</div><div>✳</div><div>Aa</div><div>◎</div></div>`);
 if(id==='mesh')return f(`<div class="art-mesh"></div><div class="art-title" style="padding-top:16px">Feel the flow.<br>Find your rhythm.</div><div class="art-text"></div>`);
 if(id==='buttons'||id==='tabs')return f(`<div class="art-eyebrow">SMALL BUT MEANINGFUL</div><div class="art-title" style="font-size:17px">Every detail matters.</div><div class="art-pill-row"><i></i><i></i><i></i></div><div class="art-pill-row"><i></i><i></i></div>`);
 if(id==='notifications')return f(`<div class="art-eyebrow">A LITTLE PEACE OF MIND</div>${['Product updates','Creative reminders','Weekly inspiration'].map(x=>`<div class="art-switch-row">${x}<i></i></div>`).join('')}`);
 if(id==='kanban')return f(`<div class="art-kanban">${['TO DO','IN PROGRESS','DONE'].map((x,i)=>`<div><strong>${x}</strong><i></i>${i?'':'<i></i>'}</div>`).join('')}</div>`);
 if(id==='timeline'||id==='progress')return f(`<div class="art-eyebrow">ONE STEP AT A TIME</div><div class="art-title" style="font-size:20px">From thought<br>to something real.</div><div class="art-timeline"><i></i><i></i><i></i><i></i></div>`);
 if(id==='navbar'||id==='footer')return f(`<div class="art-mini-nav"><b>✳ forma</b><span></span><span></span><span></span></div><div class="art-title" style="font-size:18px">A thoughtful<br>place to begin.</div>${lines}<span class="art-button"></span>`);
 if(id==='faq')return f(`<div class="art-eyebrow">GOOD QUESTIONS</div><div class="art-title" style="font-size:17px">A little clarity.</div>${[1,2,3,4].map(()=>'<div class="art-switch-row">What would you like to know?<b>+</b></div>').join('')}`);
 if(id==='profile')return f(`<div style="height:40px;background:#e5ebda;border-radius:3px;margin:-15px -15px 0"></div><div style="width:35px;height:35px;background:#bacba4;color:#fff;border:3px solid #fff;border-radius:50%;position:relative;margin:-17px 0 8px;display:grid;place-items:center;font-size:15px">L</div><div class="art-title" style="font-size:18px">Lin / Designer.</div>${lines}<span class="art-button" style="margin-top:7px"></span>`);
 if(id==='product')return f(`<div class="art-rings" style="border:0;background:#e4e9da;border-radius:65px 65px 5px 5px;width:65px;height:42px;right:20px;top:32px"></div><div style="height:47px;width:4px;background:#a2b58c;position:absolute;right:49px;top:69px"></div><div class="art-eyebrow">SLOW EVERYDAY MOMENTS</div><div class="art-title" style="font-size:18px;margin-top:13px">Light up<br>the ordinary.</div><span class="art-button"></span>`);
 if(id==='marquee')return f(`<div class="art-eyebrow">KEEP THE GOOD IDEAS COMING</div><div style="font-size:27px;font-weight:600;line-height:1.5;margin-top:14px;white-space:nowrap;color:#667f4d;letter-spacing:-1.5px;transform:rotate(-7deg)">CREATE ✳ EXPLORE<br>INSPIRE ✳ REPEAT</div>`);
 return f(`<div class="art-title">${esc(item.name)}</div>${lines}`);
}
function renderCard(item,index){const liked=favorites.has(keyOf(item)),kind=item.kind||'block',isPlayable=['block','template'].includes(kind),mood=item.mood||{design:'sage',build:'blue',verify:'sand'}[item.role]||(kind==='reference'?'sand':'neutral');return `<article class="design-card" data-item-key="${esc(keyOf(item))}"><div class="card-art ${esc(mood)}" role="button" tabindex="0" data-open="${esc(keyOf(item))}" aria-label="查看${esc(item.name)}"><span class="art-caption">${String(index+1+(view.page-1)*18).padStart(2,'0')} / ${isPlayable?'ORIGINAL EXPLORATION':kind==='reference'?'DESIGN REFERENCE':kind==='skill'?'LOCAL SKILL':'RESOURCE INDEX'}</span><span class="card-badge">${kind==='block'?'可实时编辑':kind==='template'?'整页可拼装':kind==='reference'?'DESIGN.md':kind==='skill'?'本地索引':item.projectType==='source-available'?'特殊授权':'开源资源'}</span>${thumb(item)}${isPlayable?`<div class="card-overlay"><button data-preview="${esc(item.id)}" data-kind="${kind}">${icon('eye').replace('<svg ','<svg style="display:none" ')}试试预览</button><button data-add="${esc(item.id)}" data-kind="${kind}">${kind==='template'?'使用模板':'加入拼装'} ↗</button></div>`:''}</div><div class="card-body"><div class="card-title-row"><h3><button data-open="${esc(keyOf(item))}">${esc(item.name)}</button></h3><button class="favorite-btn ${liked?'liked':''}" data-favorite="${esc(keyOf(item))}" aria-label="${liked?'取消收藏':'收藏'}${esc(item.name)}" aria-pressed="${liked}">${icon('heart')}</button></div><p class="card-desc">${esc(item.descriptionZh||item.description||'一份值得收藏的设计参考。')}</p><div class="card-footer">${(item.tags||[item.category]).filter(Boolean).slice(0,2).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}<span class="card-source"><i></i>${isPlayable?'原创 · MIT':kind==='reference'?'本地参考':kind==='skill'?roleName(item.role):esc(licenseOf(item))}</span></div></div></article>`;}

function toggleFavorite(key){favorites.has(key)?favorites.delete(key):favorites.add(key);try{localStorage.setItem(FAVS,JSON.stringify([...favorites]))}catch{toast('收藏无法保存到浏览器。',true)}navigation();if(view.name==='favorites')renderLibrary();else{$$(`[data-favorite]`).filter(e=>e.dataset.favorite===key).forEach(e=>{const liked=favorites.has(key);e.classList.toggle('liked',liked);e.setAttribute('aria-pressed',liked);e.setAttribute('aria-label',(liked?'取消收藏':'收藏')+(allItems().find(i=>keyOf(i)===key)?.name||''))})}}
function openDialog(d){if(!d.open)d.showModal();document.body.style.overflow='hidden';}
function closeDialog(d){d.close();if(!$$('dialog[open]').length)document.body.style.overflow='';}
for(const d of [details,codeDialog,infoDialog]){d.addEventListener('close',()=>{if(!$$('dialog[open]').length)document.body.style.overflow=''});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}})}
function deviceControls(scope,device='desktop'){return `<div class="device-buttons" role="group" aria-label="预览宽度">${['desktop','tablet','mobile'].map(d=>`<button data-device="${d}" data-device-scope="${scope}" class="${device===d?'active':''}" aria-pressed="${device===d}" aria-label="${{desktop:'桌面',tablet:'平板',mobile:'手机'}[d]}预览">${icon(d)}</button>`).join('')}</div>`;}
function themeControls(theme,prefix){return `<div class="field"><span>主题预设</span><select data-theme="id" data-theme-scope="${prefix}" aria-label="主题预设">${THEMES.map(t=>`<option value="${t.id}" ${theme.id===t.id?'selected':''}>${t.name}</option>`).join('')}</select></div><div class="preset-colors">${['#3d6655','#7356b7','#2563eb','#a94729','#e6f06d','#b3f572'].map(c=>`<button style="--swatch:${c}" data-color-preset="${c}" data-theme-scope="${prefix}" aria-label="应用强调色 ${c}"></button>`).join('')}</div>${[['accent','强调色'],['bg','页面底色']].map(([k,n])=>`<div class="field"><span>${n}</span><div class="color-field"><input type="color" data-theme="${k}" data-theme-scope="${prefix}" value="${esc(theme[k])}" aria-label="${n}"><input type="text" data-theme="${k}" data-theme-scope="${prefix}" value="${esc(theme[k])}" pattern="#[0-9a-fA-F]{6}" aria-label="${n}十六进制值" maxlength="7"></div></div>`).join('')}<div class="field"><span>字体方向</span><select data-theme="font" data-theme-scope="${prefix}" aria-label="字体方向">${[['sans','现代无衬线'],['serif','编辑式衬线'],['mono','等宽与技术感']].map(([v,n])=>`<option value="${v}" ${theme.font===v?'selected':''}>${n}</option>`).join('')}</select></div>${[['radius','圆角',0,40,'px'],['space','章节间距',24,120,'px']].map(([k,n,min,max,u])=>`<div class="field"><label class="range-label">${n}<output data-output="${prefix}-${k}">${theme[k]}${u}</output></label><input type="range" min="${min}" max="${max}" value="${theme[k]}" data-theme="${k}" data-theme-scope="${prefix}" aria-label="${n}"></div>`).join('')}`;}
function propsControls(block,scope){return Object.entries(block.props).map(([k,v])=>`<label class="field"><span>${{eyebrow:'上方短句 / Eyebrow',title:'主要标题',subtitle:'说明文字',button:['stats','timeline','tabs','gallery','command'].includes(block.type)?'内容列表（英文逗号分隔）':'按钮文字',secondary:'次要文字或价格'}[k]||k}</span>${['title','subtitle'].includes(k)?`<textarea rows="${k==='title'?2:3}" maxlength="4000" data-prop="${esc(k)}" data-prop-scope="${scope}">${esc(v)}</textarea>`:`<input type="text" maxlength="4000" data-prop="${esc(k)}" data-prop-scope="${scope}" value="${esc(v)}">`}</label>`).join('');}
function openDetail(item){if(item.kind==='reference'||item.kind==='opensource'||item.kind==='resource'||item.kind==='skill'){openResource(item);return}detailState={item,project:item.kind==='template'?createProject(item.id):{version:1,name:item.name,theme:{...project.theme},blocks:[createBlock(item.id)],customCSS:''},device:'desktop'};renderDetail();openDialog(details);}
function renderDetail(){const {item,project:p,device}=detailState;$('#detail-content').innerHTML=`<div class="dialog-top"><div><span class="eyebrow">YOUR PLAYGROUND / ORIGINAL DEMO</span><h2>${esc(item.name)}</h2><p>${esc(item.description)}</p></div><div class="dialog-actions"><button class="secondary-button" data-action="detail-code">${icon('code')} 查看源码</button><button class="icon-btn" data-close="detail" aria-label="关闭预览">${icon('close')}</button></div></div><div class="detail-layout"><div class="detail-preview-pane"><div class="preview-toolbar"><span><i></i> LIVE PREVIEW</span>${deviceControls('detail',device)}</div><div class="iframe-viewport" data-device="${device}" id="detail-viewport"><iframe id="detail-iframe" title="${esc(item.name)}实时预览" sandbox="allow-scripts" referrerpolicy="no-referrer"></iframe></div><p class="detail-demo-hint">试着点击预览里的按钮，或调整右侧参数。表单与商业操作均为本地演示。</p></div><aside class="detail-controls"><div class="control-group"><h3>让设计，带上你的风格。</h3>${themeControls(p.theme,'detail')}</div>${p.blocks.length===1?`<div class="control-group"><h3>改改文案</h3>${propsControls(p.blocks[0],'detail')}</div>`:'<div class="control-group"><h3>这是一张完整页面</h3><p class="source-note">把模板加入拼装台，即可逐块编辑、排序、替换与组合。</p></div>'}<p class="source-note">本站原创演示 · MIT License<br>原生 HTML + CSS + JavaScript，无需第三方运行时。</p></aside></div><div class="detail-bottom"><span>修改仅影响这份预览。把它加入拼装台，继续创作。</span><button class="primary-button" data-action="detail-add">${icon('plus')}${item.kind==='template'?'使用这个模板':'加入我的页面'}</button></div>`;$('#detail-iframe').srcdoc=generateDocument(p);}
function openResource(item){const isRef=item.kind==='reference',isSkill=item.kind==='skill';const title=isRef?'LOCAL DESIGN REFERENCE':isSkill?'LOCAL SKILL / CAPABILITY INDEX':'VERIFIED RESOURCE / OFFICIAL SOURCE';const notes=Array.isArray(item.notes)?item.notes.join('\n'):item.notes||'';const palette=(item.colors||[]).filter(c=>/^#[0-9a-f]{6}$/i.test(c));const special=item.projectType==='source-available';$('#info-content').innerHTML=`<div class="dialog-top"><div><span class="eyebrow">${title}</span><h2>${esc(item.name)}</h2></div><button class="icon-btn" data-close="info" aria-label="关闭资源详情">${icon('close')}</button></div><div class="info-body"><div class="resource-detail-title">${esc(item.name)} <span aria-hidden="true">↗</span></div><p>${esc(item.descriptionZh||item.description)}</p><div class="info-pills">${(item.tags||[]).map(t=>`<span>${esc(t)}</span>`).join('')}${special?'<span>源码可见 · 非宽松开源</span>':''}</div><dl class="resource-meta-table"><dt>资源类别</dt><dd>${esc(item.category||roleName(item.role))}</dd><dt>${isSkill?'本地位置':'代码 / 文档许可'}</dt><dd>${esc(isSkill?item.localPath:licenseOf(item))}</dd><dt>来源</dt><dd>${https(item.source)?safeLink(item.source,'查看来源 ↗'):'本地文件索引'}</dd>${!isRef&&!isSkill?`<dt>核对日期</dt><dd>${esc(item.verifiedAt||catalog.generatedAt)}</dd>`:''}</dl>${isRef?`<h3>原创模块 × 参考主题</h3><div class="reference-live-preview"><iframe id="reference-preview-iframe" title="参考主题的原创演示预览" sandbox="allow-scripts" referrerpolicy="no-referrer"></iframe></div><p class="source-note">依据文档中的语义色值套用本站原创模块；版式为原创演示，使用系统字体代替专有字体。</p><h3>从原文提取的颜色</h3><div class="reference-palette">${palette.map(c=>`<button data-copy-color="${esc(c)}" style="--s:${c}" aria-label="复制颜色 ${c}"><i></i>${esc(c)}</button>`).join('')}</div><button class="secondary-button reference-token-button" data-apply-reference="${esc(item.id)}">${icon('palette')}用这组配色，试试原创模块</button><h3>使用范围</h3><p>${esc(item.license?.document?.note||'参考文档授权以来源为准。')}</p><p>${esc(item.license?.brandAssets?.note||'品牌资产需独立授权。')}</p>`:isSkill?`<h3>它擅长什么</h3><ul>${(item.capabilities||[]).map(c=>`<li>${esc(c)}</li>`).join('')}</ul><h3>可复制的任务提示</h3><pre>${esc(item.prompt)}</pre><button class="secondary-button" data-copy-prompt="${esc(item.id)}">${icon('copy')}复制提示词</button><p class="source-note">此网页整理技能索引。运行技能需要回到支持该技能的环境，并按其真实指引执行。</p>`:`<div class="dialog-actions">${safeLink(item.docs,`${icon('external')}官方文档 / 预览`,'primary-button')}${safeLink(item.source,`${icon('code')}仓库源码`,'secondary-button')}</div><h3>源码怎么使用</h3><p>在官方文档选定组件，按其安装或复制说明放入对应框架的项目。完整源码与授权以仓库为准。</p><p>${special?'此资源有额外再分发限制。本工作台仅提供索引入口，不收录、改写或导出该项目的组件。':'本工作台没有打包此库的实现；「可玩模块」中的预览和导出均为本站原创。'}</p>${https(item.licenseUrl)?`<p>${safeLink(item.licenseUrl,'阅读许可证原文 ↗')}</p>`:''}`}<h3>索引说明</h3><div class="reference-content">${esc(notes||'根据本地技能元数据或官方仓库整理。')}</div></div>`;openDialog(infoDialog);if(isRef){const demo={version:1,name:item.name+' · 配色实验',theme:referenceTheme(item),blocks:[createBlock('hero-editorial'),createBlock('features')],customCSS:''};$('#reference-preview-iframe').srcdoc=generateDocument(demo);}}
function applyReference(id){const r=references.find(x=>x.id===id);if(!r)return;closeDialog(infoDialog);mutate(()=>project.theme=referenceTheme(r));setView('builder');toast('已应用 '+r.name+' 文档中提取的主题颜色，可继续自行调整。');}
function selectedBlock(){return project.blocks.find(b=>b.uid===selected);}
function addBlock(id){if(project.blocks.length>=100){toast('一个项目最多支持 100 个模块，请拆分为多个页面。',true);return}mutate(()=>{const b=createBlock(id);const index=project.blocks.findIndex(x=>x.uid===selected);project.blocks.splice(index<0?project.blocks.length:index+1,0,b);selected=b.uid});if(view.name!=='builder'){setView('builder')}toast('已加入页面。你可以继续调整、排序与组合。');}
function useTemplate(id){const t=TEMPLATES.find(t=>t.id===id);if(!t)return;mutate(()=>{project=createProject(id);selected=project.blocks[0]?.uid||''});setView('builder');toast('模板已打开，先前页面可用撤销恢复。');}
function addDetail(){const p=detailState.project;closeDialog(details);if(detailState.item.kind==='template'){mutate(()=>{project=structuredClone(p);selected=project.blocks[0]?.uid||''});setView('builder');toast('已采用模板及当前预览中的主题。');return}if(project.blocks.length>=100){toast('一个项目最多支持 100 个模块。',true);return}mutate(()=>{project.theme={...p.theme};const b=structuredClone(p.blocks[0]);b.uid=uid();const i=project.blocks.findIndex(x=>x.uid===selected);project.blocks.splice(i<0?project.blocks.length:i+1,0,b);selected=b.uid});setView('builder');toast('模块和你的修改，已一起加入页面。');}
function renderBuilder(){navigation();ensureSelection();const b=selectedBlock();main.innerHTML=`<div class="builder-heading"><div><div class="page-eyebrow"><i></i>A LITTLE ROOM TO PLAY</div><h1>好界面，一块块拼出来。</h1><p>选模块，改样式，看看变化。满意了，就把代码带走。</p></div><div class="builder-heading-actions"><button class="secondary-button" data-action="import-project">${icon('upload')}导入项目</button><button class="secondary-button" data-action="export-project">${icon('file')}保存项目</button><button class="primary-button" data-action="project-code">${icon('code')}复制 / 导出源码</button></div></div><div class="template-ribbon"><span>从一个模板开始</span>${TEMPLATES.map(t=>`<button data-use-template="${t.id}">${esc(t.name)} ↗</button>`).join('')}<button data-action="blank-project">空白画布 +</button></div><div class="builder-toolbar"><div class="project-title"><span>${icon('file')}</span><label class="sr-only" for="project-name">项目名称</label><input id="project-name" type="text" maxlength="100" value="${esc(project.name)}"></div><div class="builder-history"><button class="icon-btn" data-action="undo" aria-label="撤销" title="撤销 Ctrl+Z" ${undoStack.length?'':'disabled'}>${icon('undo')}</button><button class="icon-btn" data-action="redo" aria-label="重做" title="重做 Ctrl+Shift+Z" ${redoStack.length?'':'disabled'}>${icon('redo')}</button></div>${deviceControls('builder',view.device)}</div><div class="builder-main"><aside class="builder-panel left"><div class="panel-tabs" role="tablist" aria-label="拼装工具"><button data-builder-tab="layers" role="tab" aria-selected="${view.builderTab==='layers'}" class="${view.builderTab==='layers'?'active':''}">页面图层</button><button data-builder-tab="assets" role="tab" aria-selected="${view.builderTab==='assets'}" class="${view.builderTab==='assets'?'active':''}">添加模块</button></div>${view.builderTab==='layers'?`<div class="layer-list" id="layer-list">${project.blocks.map((x,i)=>`<div class="layer-item ${selected===x.uid?'active':''} ${x.hidden?'hidden-layer':''}" draggable="true" data-layer="${esc(x.uid)}" role="button" tabindex="0" aria-label="选择第 ${i+1} 层 ${esc(BLOCKS.find(d=>d.id===x.type)?.name)}"><span class="drag-grip">⠿</span>${icon('layers')}<span class="layer-name">${esc(BLOCKS.find(d=>d.id===x.type)?.name)}</span><span class="layer-index">${String(i+1).padStart(2,'0')}</span></div>`).join('')||'<div class="inspector-empty">画布还很安静。<br>加一个模块，开始吧。</div>'}</div><div class="layer-tools">${[['up','上移图层','layer-up'],['down','下移图层','layer-down'],['copy','复制图层','layer-duplicate'],['eye',b?.hidden?'显示图层':'隐藏图层','layer-hide'],['trash','移除图层','layer-remove']].map(([i,n,a])=>`<button class="icon-btn" data-action="${a}" aria-label="${n}" title="${n}" ${b?'':'disabled'}>${icon(i)}</button>`).join('')}</div><button class="add-block-btn" data-builder-tab="assets">${icon('plus')}添加一个新模块</button>`:`<label class="asset-search">${icon('search')}<input id="asset-search" type="search" placeholder="搜索模块…" aria-label="搜索可添加模块" value="${esc(view.assetSearch)}"></label><span class="search-result-count">点击加入当前图层下方</span><div class="builder-asset-list" id="asset-list">${renderAssets()}</div>`}<p class="builder-help">拖动图层可以排序，也可选中后使用上移 / 下移按钮。隐藏图层不会出现在导出页面中。项目会自动保存在当前浏览器。</p></aside><div class="builder-stage"><div class="builder-stage-top"><span><i></i> YOUR LIVE CANVAS</span><span>${project.blocks.filter(x=>!x.hidden).length} 个可见模块 · 原生 HTML</span></div><div class="builder-preview" id="builder-viewport" data-device="${view.device}"><iframe id="builder-iframe" title="我的页面实时预览" sandbox="allow-scripts" referrerpolicy="no-referrer"></iframe></div><div class="stage-bottom"><span>点击预览中的模块，定位到对应图层。</span><span id="device-label">${{desktop:'自动适配',tablet:'768 px',mobile:'375 px'}[view.device]}</span></div></div><aside class="builder-panel right"><div class="inspector-title">设计检查器 / INSPECTOR</div><div class="inspector-section"><h3>全局主题 <span>↗</span></h3>${themeControls(project.theme,'builder')}</div>${b?`<div class="inspector-section" id="block-inspector"><h3>${esc(BLOCKS.find(x=>x.id===b.type)?.name)} / 内容</h3>${propsControls(b,'builder')}</div>`:'<div class="inspector-empty"><span>✳</span>选择一个模块，<br>改改它的文字。</div>'}<div class="inspector-section"><h3>自由修改 CSS</h3><label class="sr-only" for="custom-css">自定义 CSS</label><textarea class="css-input" id="custom-css" spellcheck="false" placeholder="/* 试试微调 */&#10;.section-heading h2 {&#10;  letter-spacing: -2px;&#10;}">${esc(project.customCSS)}</textarea><button class="secondary-button css-apply" data-action="apply-css">应用到预览 ↗</button><p class="import-notice">源码编辑器还支持修改完整 HTML 并在隔离预览中运行。</p></div></aside></div>`;
 $('#builder-iframe').srcdoc=generateDocument(project,{selectable:true});$('#project-name').addEventListener('change',e=>mutate(()=>project.name=e.target.value.trim()||'我的作品',{render:false}));const a=$('#asset-search');if(a)a.addEventListener('input',e=>{view.assetSearch=e.target.value;$('#asset-list').innerHTML=renderAssets()});setupDrag();}
function renderAssets(){const q=view.assetSearch.trim().toLowerCase();const items=BLOCKS.filter(b=>[b.name,b.id,b.category,...b.tags].join(' ').toLowerCase().includes(q));return items.length?items.map(b=>`<button class="asset-item" data-add="${b.id}"><span>${{首屏:'✳',内容:'◈',商业:'↗',导航:'≡',数据:'▥',表单:'⌘',组件:'◇',动效:'◎'}[b.category]||'✳'}</span><div><b>${esc(b.name)}</b><small>${esc(b.category)}</small></div><i>+</i></button>`).join(''):'<div class="inspector-empty">没有匹配的模块。</div>';}
function setupDrag(){const list=$('#layer-list');if(!list)return;list.addEventListener('dragstart',e=>{const item=e.target.closest('[data-layer]');if(!item)return;draggedLayer=item.dataset.layer;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',draggedLayer)});list.addEventListener('dragover',e=>{const item=e.target.closest('[data-layer]');if(!item)return;e.preventDefault();$$('.drag-over',list).forEach(x=>x.classList.remove('drag-over'));item.classList.add('drag-over')});list.addEventListener('dragleave',e=>e.target.closest('[data-layer]')?.classList.remove('drag-over'));list.addEventListener('drop',e=>{e.preventDefault();const target=e.target.closest('[data-layer]');const from=project.blocks.findIndex(b=>b.uid===draggedLayer),to=project.blocks.findIndex(b=>b.uid===target?.dataset.layer);if(from<0||to<0||from===to)return;mutate(()=>{const[b]=project.blocks.splice(from,1);project.blocks.splice(to,0,b);selected=b.uid});draggedLayer=''});list.addEventListener('dragend',()=>{$$('.drag-over',list).forEach(x=>x.classList.remove('drag-over'));draggedLayer=''})}
function schedulePreview(){clearTimeout(previewTimer);previewTimer=setTimeout(()=>{const iframe=$('#builder-iframe');if(iframe)iframe.srcdoc=generateDocument(project,{selectable:true})},100);}
function selectLayer(id){if(selected===id)return;const block=project.blocks.find(x=>x.uid===id);if(!block)return;selected=id;$$('[data-layer]').forEach(el=>el.classList.toggle('active',el.dataset.layer===id));const panel=$('#block-inspector');if(panel)panel.innerHTML=`<h3>${esc(BLOCKS.find(x=>x.id===block.type)?.name)} / 内容</h3>${propsControls(block,'builder')}`;else renderBuilder();}
function layerAction(action){const i=project.blocks.findIndex(b=>b.uid===selected);if(i<0)return;if(action==='up'&&i===0||action==='down'&&i===project.blocks.length-1)return;if(action==='duplicate'&&project.blocks.length>=100){toast('一个项目最多支持 100 个模块。',true);return}mutate(()=>{if(action==='up'){[project.blocks[i-1],project.blocks[i]]=[project.blocks[i],project.blocks[i-1]]}if(action==='down'){[project.blocks[i+1],project.blocks[i]]=[project.blocks[i],project.blocks[i+1]]}if(action==='duplicate'){const b=structuredClone(project.blocks[i]);b.uid=uid();project.blocks.splice(i+1,0,b);selected=b.uid}if(action==='hide')project.blocks[i].hidden=!project.blocks[i].hidden;if(action==='remove'){project.blocks.splice(i,1);selected=project.blocks[Math.min(i,project.blocks.length-1)]?.uid||''}})}
function changeTheme(el){const scope=el.dataset.themeScope,key=el.dataset.theme;let target=scope==='detail'?detailState?.project:project;if(!target)return;let value=el.value;if(key==='id'){const t=THEMES.find(x=>x.id===value);if(!t)return;if(scope==='builder')mutate(()=>project.theme={...t});else{target.theme={...t};renderDetail()}return}if(['accent','bg'].includes(key)&&!/^#[0-9a-f]{6}$/i.test(value))return;if(['radius','space'].includes(key))value=Number(value);if(scope==='builder'){mutate(()=>project.theme=normalizeTheme({...project.theme,[key]:value}),{render:false})}else{target.theme=normalizeTheme({...target.theme,[key]:value});$('#detail-iframe').srcdoc=generateDocument(target)}$$(`[data-theme="${key}"][data-theme-scope="${scope}"]`).forEach(x=>{if(x!==el)x.value=String(value)});$$(`[data-output="${scope}-${key}"]`).forEach(x=>x.textContent=value+'px');}
function renderThemes(){main.innerHTML=`<div class="page-eyebrow"><i></i>A PALETTE OF POSSIBILITIES</div><div class="page-heading"><div><h1>同一个想法，<em>不同的气质。</em></h1><p>颜色、字体、圆角与留白，组成你的设计语言。选个方向，再慢慢调成自己的样子。</p></div><div class="heading-art" aria-hidden="true"><div class="heading-orbit"><span>✳</span></div></div></div><div class="theme-gallery">${THEMES.map(t=>`<article class="theme-card"><div class="theme-preview" style="--t-bg:${t.bg};--t-ink:${t.ink};--t-accent:${t.accent};--t-radius:${t.radius/3}px;--t-font:${t.font==='serif'?'Georgia,serif':t.font==='mono'?'Consolas,monospace':'inherit'}"><small>DESIGNED TO FEEL LIKE YOU</small><h3>Good ideas.<br>Your style.</h3><i></i><span>✳</span></div><div class="theme-card-body"><div><h3>${esc(t.name)}</h3><small>${t.id.toUpperCase()}</small></div><div class="theme-swatch-list">${[t.bg,t.surface,t.accent,t.ink,t.muted].map(c=>`<i style="--s:${c}" title="${c}"></i>`).join('')}</div><div class="theme-card-actions"><button class="secondary-button" data-copy-theme="${t.id}">${icon('copy')}复制 CSS</button><button class="primary-button" data-apply-theme="${t.id}">应用主题 ↗</button></div></div></article>`).join('')}</div><div class="theme-lab-bottom"><div><h2>喜欢某个品牌的色彩语言？</h2><p>本地设计参考提取了真实文档中的色值。先借一个起点，再设计自己的完整系统。</p></div><button class="secondary-button" data-section="references">探索 ${references.length} 份设计参考 ${icon('arrow')}</button></div>`;}
function themeCSS(t){const root=generateParts({version:1,name:'主题',theme:t,blocks:[],customCSS:''}).css.split('\n')[0];return '/* Design Atlas original theme · MIT */\n'+root.replace('{','{\n  ').replaceAll(';',';\n  ').replace('}','\n}');}
async function copy(text,label='已复制到剪贴板'){try{await navigator.clipboard.writeText(text);toast(label);return true}catch{const area=document.createElement('textarea');area.value=text;area.style.cssText='position:fixed;opacity:0;inset:0 auto auto 0;';const host=codeDialog.open?$('#code-content'):infoDialog.open?$('#info-content'):document.body;host.append(area);area.select();let ok=false;try{ok=document.execCommand('copy')}catch{}area.remove();if(ok){toast(label);return true}toast('剪贴板权限不可用，请在源码框中全选复制，或下载文件。',true);return false}}
function download(text,name,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('下载已开始：'+name);}
const filename=name=>(name||'my-design').replace(/[\\/:*?"<>|\x00-\x1f]/g,'-').slice(0,80);
function openCode(p){const parts=generateParts(p);codeState={project:structuredClone(p),tab:'full',files:{full:generateDocument(p),html:parts.html,css:parts.css,js:parts.js,json:JSON.stringify(p,null,2)},custom:false};renderCode();openDialog(codeDialog);}
function renderCode(){const state=codeState;$('#code-content').innerHTML=`<div class="dialog-top"><div><span class="eyebrow">YOUR DESIGN. YOUR CODE.</span><h2>把好设计，带进你的项目。</h2><p>${esc(state.project.name)} · 原生 HTML / CSS / JavaScript</p></div><button class="icon-btn" data-close="code" aria-label="关闭源码">${icon('close')}</button></div><div class="code-header-tabs" role="tablist" aria-label="源码格式">${[['full','完整 HTML'],['html','HTML 片段'],['css','CSS'],['js','JavaScript'],['json','项目 JSON']].map(([id,n])=>`<button data-code-tab="${id}" role="tab" aria-selected="${state.tab===id}" class="${state.tab===id?'active':''}">${n}</button>`).join('')}<span>MIT LICENSE · NO DEPENDENCIES</span></div><label class="sr-only" for="source-editor">可编辑的${{full:'完整 HTML',html:'HTML 片段',css:'CSS',js:'JavaScript',json:'项目 JSON'}[state.tab]}源码</label><textarea id="source-editor" class="code-editor" spellcheck="false" wrap="off">${esc(state.files[state.tab])}</textarea><div class="code-footer"><small id="code-hint">完整 HTML 可直接保存为 .html 打开。修改后，可先在隔离沙盒里试运行。片段与 CSS / JS 需一起使用。</small><div><button class="secondary-button" data-action="run-code">${icon('eye')}试运行修改</button><button class="secondary-button" data-action="download-code">${icon('download')}下载</button><button class="primary-button" data-action="copy-code">${icon('copy')}复制代码</button></div></div>`;$('#source-editor').addEventListener('input',e=>{codeState.files[codeState.tab]=e.target.value;codeState.custom=true});$('#source-editor').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const el=e.target,start=el.selectionStart,end=el.selectionEnd;el.setRangeText('  ',start,end,'end');codeState.files[codeState.tab]=el.value}});}
function documentFromCode(){if(codeState.tab==='full')return codeState.files.full;if(codeState.tab==='json')return generateDocument(validateProject(JSON.parse(codeState.files.json)));return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="${CSP}"><title>${esc(codeState.project.name)}</title><style>${codeState.files.css.replace(/<\/style/gi,'<\\/style')}</style></head><body>${codeState.files.html}<script>${codeState.files.js.replace(/<\/script/gi,'<\\/script')}</script></body></html>`;}
function runCode(){let html;try{html=documentFromCode();if(html.length>16*1024*1024)throw Error('源码超过 16 MB，请缩小后再预览。');if(!/<head(?:\s|>)/i.test(html))html=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body>${html}</body></html>`;html=sandboxDocument(html)}catch(e){toast('无法预览：'+e.message,true);return}closeDialog(codeDialog);$('#info-content').innerHTML=`<div class="dialog-top"><div><span class="eyebrow">YOUR CUSTOM CODE / SANDBOX</span><h2>源码修改预览</h2><p>修改在隔离环境运行。返回源码可继续编辑或下载。</p></div><div class="dialog-actions"><button class="secondary-button" data-action="return-code">${icon('code')}返回源码</button><button class="icon-btn" data-close="info" aria-label="关闭源码预览">${icon('close')}</button></div></div><div class="detail-preview-pane"><div class="iframe-viewport"><iframe id="custom-code-iframe" title="自定义源码沙盒预览" sandbox="allow-scripts" referrerpolicy="no-referrer" style="height:65vh"></iframe></div><p class="source-note">本次源码修改可复制或下载；可视化拼装项目保持原有结构。若要保存可继续拼装的修改，请在检查器或项目 JSON 中编辑。</p></div>`;openDialog(infoDialog);$('#custom-code-iframe').srcdoc=html;}
function about(){const date=catalog.generatedAt||'2026-10-22';$('#info-content').innerHTML=`<div class="dialog-top"><div><span class="eyebrow">A SPACE FOR YOUR NEXT IDEA</span><h2>关于 Design Atlas</h2></div><button class="icon-btn" data-close="info" aria-label="关闭说明">${icon('close')}</button></div><div class="info-body"><h3>从一个想法，到一份可运行的界面</h3><p>这是一个前端设计探索与拼装工作台：${BLOCKS.length} 个原创模块、${TEMPLATES.length} 套整页模板、${THEMES.length} 种主题、${references.length} 份本地设计参考、${catalog.resources.length} 个源码资源和 ${catalog.skills.length} 项本地技能索引。</p><h3>三个容易混淆的地方</h3><ul><li>可玩模块是本工作台独立编写的 HTML / CSS / JavaScript 演示，可编辑、组合、复制和导出，采用 MIT 许可证。</li><li>设计参考来自本地 DESIGN.md；提取名称、摘要与颜色，不复制品牌页面、图片、字体或资产。文档许可与品牌资产许可分列展示。</li><li>开源资源索引提供官方文档、演示与仓库入口，库本身未打包进本工作台。React Bits 等特殊许可资源有独立标识，不再分发其组件。</li></ul><h3>目录的范围</h3><p>本地索引扫描技能安装目录及 DESIGN.md 文件，实际收录范围见随附 README。互联网资源数量持续变化，本次为截至 ${esc(date)} 核对的精选目录，不代表穷尽所有前端设计项目。可修改 data/catalog.json 扩充，再运行离线打包脚本。</p><h3>保存与可离线使用</h3><p>项目和收藏保存在当前浏览器的 localStorage；切换域名、浏览器或清理存储后不会自动同步。使用「保存项目」导出 JSON，可在别处重新导入。导出的完整 HTML、随附 offline.html 都不依赖外部 CDN。本站不收集或上传表单数据。</p><h3>键盘与辅助操作</h3><ul><li><kbd>/</kbd>：资源库聚焦搜索。</li><li><kbd>Ctrl / ⌘ + Z</kbd>：拼装台撤销；加 Shift 重做。输入框保留浏览器自身的撤销行为。</li><li><kbd>Ctrl / ⌘ + S</kbd>：在拼装台下载项目 JSON。</li><li><kbd>Esc</kbd>：关闭当前弹窗。标签切换、图层选择与按钮均可用键盘操作。</li></ul><h3>扩充目录</h3><p>在项目目录执行 <code>node scripts/refresh-local-catalog.mjs</code> 重新扫描本地技能，再执行 <code>node scripts/build-offline.mjs</code> 更新离线文件。开源目录使用已核对的固定快照，不会在网页打开时自动联网抓取。</p><p>${safeLink('https://github.com/VoltAgent/awesome-design-md','本地参考库的上游 ↗')} · ${safeLink('https://ui.shadcn.com/docs/directory','探索更多官方登记的社区 registry ↗')}</p></div>`;openDialog(infoDialog);}

document.addEventListener('click',e=>{const el=e.target.closest('button,a,[data-open],[data-layer]');if(!el)return;
 if(el.dataset.view){setView(el.dataset.view);return}if(el.dataset.section){setView('library',el.dataset.section);return}if(el.dataset.librarySection){view.section=el.dataset.librarySection;view.filter='全部';view.page=1;render();return}if(el.dataset.filter){view.filter=el.dataset.filter;view.page=1;renderLibrary();return}if(el.dataset.layout){view.layout=el.dataset.layout;renderLibrary();return}if(el.dataset.page){view.page=Number(el.dataset.page);updateGrid();$('.section-toolbar')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return}
 if(el.dataset.favorite){toggleFavorite(el.dataset.favorite);return}if(el.dataset.preview){const item=el.dataset.kind==='template'?TEMPLATES.map(t=>({...t,kind:'template'})).find(t=>t.id===el.dataset.preview):BLOCKS.find(t=>t.id===el.dataset.preview);if(item)openDetail(item);return}if(el.dataset.add){el.dataset.kind==='template'?useTemplate(el.dataset.add):addBlock(el.dataset.add);return}if(el.dataset.open){const item=allItems().find(i=>keyOf(i)===el.dataset.open);if(item)openDetail(item);return}
 if(el.dataset.close){closeDialog({detail:details,code:codeDialog,info:infoDialog}[el.dataset.close]);return}if(el.dataset.builderTab){view.builderTab=el.dataset.builderTab;renderBuilder();return}if(el.dataset.layer){selectLayer(el.dataset.layer);return}
 if(el.dataset.device){const scope=el.dataset.deviceScope;const d=el.dataset.device;if(scope==='builder'){view.device=d;$('#builder-viewport').dataset.device=d;$('#device-label').textContent={desktop:'自动适配',tablet:'768 px',mobile:'375 px'}[d]}else{detailState.device=d;$('#detail-viewport').dataset.device=d}$$(`[data-device-scope="${scope}"]`).forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',b===el)});return}
 if(el.dataset.colorPreset){const scope=el.dataset.themeScope;if(scope==='builder')mutate(()=>project.theme.accent=el.dataset.colorPreset);else{detailState.project.theme.accent=el.dataset.colorPreset;renderDetail()}return}
 if(el.dataset.copyColor){copy(el.dataset.copyColor,'色值已复制：'+el.dataset.copyColor);return}if(el.dataset.applyReference){applyReference(el.dataset.applyReference);return}if(el.dataset.copyPrompt){const s=catalog.skills.find(x=>x.id===el.dataset.copyPrompt);if(s)copy(s.prompt,'任务提示已复制，可在支持此技能的环境中使用。');return}
 if(el.dataset.useTemplate){useTemplate(el.dataset.useTemplate);return}if(el.dataset.applyTheme){const t=THEMES.find(x=>x.id===el.dataset.applyTheme);mutate(()=>project.theme={...t});setView('builder');toast('主题已应用。');return}if(el.dataset.copyTheme){copy(themeCSS(THEMES.find(x=>x.id===el.dataset.copyTheme)),'主题 CSS 变量已复制。');return}
 if(el.dataset.codeTab){codeState.tab=el.dataset.codeTab;renderCode();return}
 const action=el.dataset.action;if(!action)return;
 if(action==='undo')undo();else if(action==='redo')redo();else if(action.startsWith('layer-'))layerAction(action.slice(6));else if(action==='project-code')openCode(project);else if(action==='detail-code')openCode(detailState.project);else if(action==='detail-add')addDetail();else if(action==='import-project')$('#project-file').click();else if(action==='export-project')download(JSON.stringify(project,null,2),filename(project.name)+'.atlas.json','application/json');else if(action==='blank-project'){mutate(()=>{project={version:1,name:'我的新作品',theme:{...project.theme},blocks:[],customCSS:''};selected='';view.builderTab='assets'});toast('空白画布已准备好。上一个页面可以撤销恢复。')}else if(action==='apply-css'){mutate(()=>project.customCSS=$('#custom-css').value.slice(0,50000),{render:false});toast('自定义 CSS 已应用并保存。')}else if(action==='copy-code')copy(codeState.files[codeState.tab]);else if(action==='download-code'){const extensions={full:'html',html:'html',css:'css',js:'js',json:'json'};download(codeState.files[codeState.tab],filename(codeState.project.name)+(codeState.tab==='html'?'.fragment':'')+'.'+extensions[codeState.tab],codeState.tab==='json'?'application/json':'text/plain;charset=utf-8')}else if(action==='run-code')runCode();else if(action==='return-code'){closeDialog(infoDialog);renderCode();openDialog(codeDialog)}else if(action==='clear-filters'){if(view.name==='favorites')setView('library','blocks');else{view.filter='全部';view.q='';view.page=1;renderLibrary()}}
});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.theme){if(el.tagName!=='SELECT')changeTheme(el);return}if(el.dataset.prop){const scope=el.dataset.propScope,key=el.dataset.prop;if(scope==='detail'){detailState.project.blocks[0].props[key]=el.value;$('#detail-iframe').srcdoc=generateDocument(detailState.project)}else{const b=selectedBlock();if(b)mutate(()=>b.props[key]=el.value,{render:false})}}});
document.addEventListener('change',e=>{if(e.target.matches('select[data-theme]'))changeTheme(e.target)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar').classList.contains('open'))closeSidebar();const el=e.target,isInput=/^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName)||el.isContentEditable;if(e.key==='/'&&!isInput&&!$$('dialog[open]').length){const search=$('#library-search');if(search){e.preventDefault();search.focus()}}if((e.ctrlKey||e.metaKey)&&!isInput&&view.name==='builder'&&!$$('dialog[open]').length){if(e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}if(e.key.toLowerCase()==='s'){e.preventDefault();download(JSON.stringify(project,null,2),filename(project.name)+'.atlas.json','application/json')}}if(['Enter',' '].includes(e.key)&&el.matches('[data-open],[data-layer]')&&el.tagName!=='BUTTON'){e.preventDefault();el.click()}if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)&&el.getAttribute('role')==='tab'){const tabs=$$('[role="tab"]',el.parentElement);if(!tabs.length)return;e.preventDefault();const i=tabs.indexOf(el);const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].click();const selector=tabs[n].dataset.librarySection?`[data-library-section="${tabs[n].dataset.librarySection}"]`:tabs[n].dataset.builderTab?`[data-builder-tab="${tabs[n].dataset.builderTab}"]`:`[data-code-tab="${tabs[n].dataset.codeTab}"]`;$(selector)?.focus()}});
window.addEventListener('message',e=>{const frame=$('#builder-iframe');if(e.source!==frame?.contentWindow||e.data?.type!=='atlas-select'||typeof e.data.uid!=='string')return;if(project.blocks.some(b=>b.uid===e.data.uid))selectLayer(e.data.uid)});
$('#project-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>16*1024*1024)throw Error('项目文件过大，最多支持 16 MB。');const p=validateProject(JSON.parse(await file.text()));mutate(()=>{project=p;selected=p.blocks[0]?.uid||''});setView('builder');toast('项目已导入。之前的页面可通过撤销恢复。')}catch(err){toast('导入失败：'+err.message,true)}});
$('#mobile-menu').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#sidebar-backdrop').hidden=false;$('#mobile-menu').setAttribute('aria-expanded','true');syncSidebar();document.body.style.overflow='hidden';$('#close-sidebar').focus()});$('#close-sidebar').addEventListener('click',closeSidebar);matchMedia('(max-width:760px)').addEventListener('change',syncSidebar);$('.logo').addEventListener('click',e=>{e.preventDefault();setView('library','blocks')});$('#sidebar-backdrop').addEventListener('click',closeSidebar);$('#about-button').addEventListener('click',about);$('#keyboard-help').addEventListener('click',about);
window.addEventListener('pagehide',()=>{if(saveTimer){try{localStorage.setItem(STORAGE,JSON.stringify(project))}catch{}}});

async function boot(){try{if(window.__ATLAS_DATA__){catalog=window.__ATLAS_DATA__.catalog;references=window.__ATLAS_DATA__.references}else{const responses=await Promise.all([fetch('./data/catalog.json'),fetch('./data/local-references.json')]);if(responses.some(r=>!r.ok))throw Error('资源目录加载失败。');[catalog,references]=await Promise.all(responses.map(r=>r.json()))}if(!Array.isArray(catalog.skills)||!Array.isArray(catalog.resources)||!Array.isArray(references))throw Error('目录数据格式不正确。');const hash=location.hash.slice(1);if(['builder','themes','favorites'].includes(hash))view.name=hash;render();syncSidebar();if(bootWarning)toast('已使用新草稿，详情见页面上方说明。',true)}catch(err){main.innerHTML=`<div class="read-error"><h1>工作台还差一步，就能打开。</h1><p>如果你直接双击了 index.html，请改为打开随附的 <b>offline.html</b>；或运行项目里的「启动工作台.cmd」。</p><pre>node scripts/serve.mjs\n\n打开 http://127.0.0.1:4317</pre><p>${esc(err.message)}</p></div>`;toast('资源加载失败，请查看页面说明。',true)}hydrateIcons();}
boot();
